 if(gate?.action==='cossenne-shortcut'){if(!rules.expeditionState(state,gate.orchardQuest).choice)say('Closed return path','Restore this site from its first landing and decide its final claim to open the return shortcut.');else void warp(gate.to,...gate.arrival);return true;}
 if(gate?.action==='cossenne-watercraft'){if(!state.cybressa?.watercraft)say('Shrine landing','You need Alice’s personal river craft. Find her on the Western Causeway, west of the mountain pass.');else void warp(gate.to,...gate.arrival);return true;}
 if(gate?.action==='cossenne-expedition'){if(!rules.orchardPassage(state,map.orchardQuest,map.questStage))say('Site passage',orchardNextStep(state,map.orchardQuest));else void warp(gate.to,...gate.arrival);return true;}
 if(gate?.to==='cossenne'&&!q.events.includes('CH05-E01')){showDialogue([line('Cossenne','The road emerges between working orchards. No line of soldiers waits at the gate.'),line('Dame Matilda de Clare','He has withdrawn his garrison. Cowardice, dressed up as kindness.'),line('Aimon','Then who would we have been fighting here?','CHR-AIMON'),line('Warden Ismail ibn Umar','My soldiers have left. These families have not. Walk with me before you ask for the town.','LDR-04')],()=>{if(commit(()=>rules.cossenneEvent(state,'CH05-E01')))void warp('cossenne',3,17,'right');});return true;}
 if(id==='area-sign'&&ORCHARD_ROUTES[room]){a.routeGuide();return true;}
