 if(COSSENNE_WALK[walkId]){showDialogue(COSSENNE_WALK[walkId].map(([name,text])=>line(name,text,name.startsWith('Warden')?'LDR-04':name==='Aimon'?'CHR-AIMON':null)),()=>commit(()=>rules.cossenneWalk(state,walkId)));return true;}
 if(id==='cs-warden-local'){say('Warden Ismail ibn Umar',state.fates?.['LDR-04']==='SPARED'?'The occupation’s officer signs the orders now. I hear the household disputes and take them to him. Someone has to keep speaking if the orchards are to survive.':'The garrison is gone. Speak to the families, watch the partners at work and hear the story at our shrine. I will wait in the inner garden.');return true;}
 if(id==='cs-family'){say('Family at prayer','A mother lifts her hands towards the morning light. Her youngest copies the gesture, then peeks at a piece of fruit hidden in his palm. The words differ from Civeton’s; the pause before the meal feels familiar.');return true;}
