 if(id==='cs-waterkeeper'){if(q.waterDone){say('Waterkeeper Ali ibn Khalil','Both channels are running. The water reaches the burn ward and the orchard ditch again. Your reward is recorded.');return true;}showDialogue([{...line('Waterkeeper Ali ibn Khalil',q.waterAccepted?'Open the western nursery valve and the eastern reservoir valve inside town, then report here. '+q.valves.length+'/2 opened.':'The army closed two reservoir valves to fill its wagon tanks. Then the repair crew was drafted. Our outer ditch ran dry and the wildfire crossed it. Open the western nursery valve and the eastern reservoir valve, then return. I can give you 900 doubloons and three Poultices.'),choices:[{text:q.valves.length===2?'Report the restored channels.':q.waterAccepted?'Keep working.':'I will reopen the valves.',action:()=>{if(commit(()=>rules.cossenneState(state).valves.length===2?rules.finishCossenneWater(state):rules.acceptCossenneWater(state)))say('Waterkeeper Ali ibn Khalil',rules.cossenneState(state).waterDone?'The ditch is filling. Received 900 doubloons and three Poultices.':'Objective: open the western nursery valve at the southwest ditch, then the eastern reservoir valve beside the waterkeeper. These are the two labelled valve wheels inside Cossenne. Return here when both are open; the reward is 900 doubloons and three Poultices.');}},{text:'Later.',action:()=>{}}]}]);return true;}
 if(id.startsWith('cs-sluice-')){const side=id.split('-').at(-1);let done=false;if(commit(()=>done=rules.cossenneValve(state,side)))say('Reservoir valve',done?'The wheel turns stiffly. Water begins moving through the '+side+' channel. Report to the waterkeeper after opening both.':rules.cossenneState(state).valves.includes(side)?'The valve is open; water is running.':'Speak to the waterkeeper before changing the supply.');return true;}
 if(id==='cs-two-prayers'){if(!q.events.includes('CH05-E03')){say('Comparison notebook','Hear the account from the shrine reader first, then return here to compare it with Civeton’s prayer.');return true;}if(commit(()=>rules.cossenneEvent(state,'CH05-O01')))record('Two Prayers · Cossenne',['A collection of shared images, with no combat bonus. Further accounts can be gathered in later towns.','Civeton: darkness before the first light; a duty to guide those still lost.','Cossenne: darkness before a radiant gift; a duty to pass that gift to strangers.','Names and gestures differ. The recurring lamp, lost traveller and offered hand are recorded side by side. The collection continues towards Botrune.']);return true;}
 if(id==='cs-boundary'){if(!state.fates?.['LDR-04'])say('Marasen road','Hear Ismail’s challenge in the shrine fort and settle his fate before the column moves on.');else if(!q.events.includes('CH05-E06'))showDialogue([line('General William de Montfort','Four victories. You ought to be proud, Aimon.','CHR-KURG'),line('Aimon','I do not feel proud.','CHR-AIMON'),line('General William de Montfort','Certainty will not follow you down every road. Duty must hold when it fails. Remember why you came.','CHR-KURG'),line('Marasen road','Stonecut Pass leads towards Marasen. That chapter is not yet open. Cossenne and every earlier road remain available.')],()=>commit(()=>rules.cossenneEvent(state,'CH05-E06')));else say('Marasen road','Stonecut Pass and Marasen are the next chapter. Keep exploring Cossenne or return along any earlier road.');return true;}
 const match=id.match(/^ow-(grove|shrine)-(keeper|record-([012])|control-([012])|resolution)$/);if(!match)return false;
 const key=match[1],part=match[2],p=rules.expeditionState(state,key),name=key==='grove'?'Grove attendant':'Archive attendant';
 if(part==='keeper'){if(p.claimed){say(name,key==='grove'?(p.choice==='a'?'Water feeds the replacement trees. The hospice carries water by hand while a larger repair is arranged.':'The burn ward has clean water. We keep the seedlings damp by hand until a larger repair is arranged.'):(p.choice==='a'?'Copies are going to households on both banks. The original stays dry in its case.':'The original remains with supervised local custodians. Visiting families can ask to read it.'));return true;}const reward=key==='grove'?'1,200 doubloons, three Training Tonics and a Pilgrim Bell keepsake':'1,200 doubloons, two Training Tonics and two Emergency Evacs';showDialogue([{...line(name,p.choice?'Your decision is recorded. Your reward is ready: '+reward+'. Choice bonus: '+choiceRewardText('orchard_'+key,p.choice)+'.':p.accepted?orchardNextStep(state,key):ORCHARD_BRIEFS[key]+' Reward: '+reward+'.'),choices:[{text:p.choice?'Collect the reward.':p.accepted?'Continue exploring.':'I will follow the trail.',action:()=>{let claimed=false;if(commit(()=>{const current=rules.expeditionState(state,key);if(current.choice)claimed=rules.claimOrchardExpedition(state,key);else rules.acceptOrchardExpedition(state,key);})){if(claimed)say(name,'Received '+reward+'.'+(key==='grove'?' The old bell is a keepsake; Pilgrimp’s evolution branches are chosen by level in the current game.':''));}}},{text:'Leave for now.',action:()=>{}}]}]);return true;}
 if(part.startsWith('record-')){const stage=Number(match[3]);if(!p.accepted){say('Site record','Speak to the entrance attendant before beginning the survey.');return true;}if(stage>0&&!rules.orchardPassage(state,key,stage-1)){say('Site record','Finish the earlier stretch before surveying this record.');return true;}if(!p.records.includes(stage)&&!commit(()=>rules.orchardRecord(state,key,stage)))return true;const pages=ORCHARD_RECORDS[key][stage];record(pages[0],[...pages.slice(1),'Next objective: '+orchardNextStep(state,key)]);return true;}
 if(part.startsWith('control-')){if(!p.records.includes(1)){say('Channel controls','Read the repair instructions beside these wheels first.');return true;}openModal(key==='grove'?'Restore the spring channels':'Drain the shrine cloister','<p>'+escapeHTML(ORCHARD_RECORDS[key][1][1])+'</p><p><b>Current:</b> '+p.rings.join(' · ')+' · <b>Target:</b> '+rules.ORCHARD_TARGETS[key].join(' · ')+'</p><p>'+(p.solved?'The channels are restored and stay open.':'Each wheel changes only its own setting. No timer.')+'</p><div class="modal-actions">'+[0,1,2].map(n=>'<button data-orchard-wheel="'+n+'" '+(p.solved?'disabled':'')+'>'+['Left','Middle','Right'][n]+' · '+p.rings[n]+'</button>').join('')+'<button id="orchard-reset" '+(p.solved?'disabled':'')+'>Reset to zero</button><button id="orchard-assist" '+(p.solved?'disabled':'')+'>Ask a '+(key==='grove'?'Grass':'Water')+' partner</button></div>');for(const el of a.document.querySelectorAll('[data-orchard-wheel]'))el.onclick=()=>{if(commit(()=>rules.orchardControl(state,key,Number(el.dataset.orchardWheel))))again();};$('#orchard-reset').onclick=()=>{if(commit(()=>rules.orchardControl(state,key,0,true)))again();};$('#orchard-assist').onclick=()=>{let done=false;if(commit(()=>done=rules.orchardAssist(state,key))){if(done)again();else a.toast('A living '+(key==='grove'?'Grass':'Water')+' partner is needed.');}};return true;}
 if(part==='resolution'){if(p.choice){say(name,'Your decision is recorded. Return to the entrance attendant for your reward.');return true;}const guard=key==='grove'?'TRN-C05-005':'TRN-C05-007';if(p.records.length!==3||!p.solved||!state.defeatedTrainers.includes(guard)){say(name,orchardNextStep(state,key));return true;}const labels=key==='grove'?['Supply replacement trees first.','Supply the temporary burn ward first.']:['Share copies with households on both banks.','Keep the register under local custody.'];showDialogue([{...line(ORCHARD_RECORDS[key][2][0],ORCHARD_RECORDS[key][2][2]),choices:labels.map((text,i)=>({text,action:()=>showDialogue([{...line('Confirm this decision',text+' This is permanent. Choice bonus: '+choiceRewardText('orchard_'+key,i?'b':'a')+'. The standard expedition prize is also retained.'),choices:[{text:'Confirm.',action:()=>{let done=false;if(commit(()=>done=rules.orchardChoice(state,key,i?'b':'a'))&&done)say(name,'The decision is recorded. Return to the entrance attendant for your reward.');}},{text:'Reconsider.',action:again}]}])}))}]);return true;}
 return true;
